import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int y;
        int capacity;
        int flow;
        int cost;

        Edge(int y, int capacity, int flow, int cost) {
            this.y = y;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = 1000000000000000000L;
    static final int MAXNODES = 1000007;
    static List<Integer>[] adj = new ArrayList[MAXNODES];
    static List<Edge> edgesList = new ArrayList<>();
    static long totalCostAccum = 0;
    static long[] distArr = new long[MAXNODES];
    static int[] predArr = new int[MAXNODES];
    static int[] peArr = new int[MAXNODES];
    static int[] inQueueFlag = new int[MAXNODES];

    static int src = MAXNODES - 2;
    static int tgt = MAXNODES - 1;

    static int n, m, k, c, d;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static int mod(int a) {
        int MOD = 1000000007;
        return ((a % MOD) + MOD) % MOD;
    }

    static int product(int a, int b) {
        int MOD = 1000000007;
        return (int)((a * 1L * b) % MOD);
    }

    static int fastPow(int a, int k) {
        int res = 1;
        while (k > 0) {
            if ((k & 1) == 1) res = product(res, a);
            a = product(a, a);
            k >>= 1;
        }
        return res;
    }

    static int modularInverse(int a) {
        int b = fastPow(a, 1000000005);
        assert product(a, b) == 1;
        return b;
    }

    static int residual(int x) {
        Edge e = edgesList.get(x);
        return e.capacity - e.flow;
    }

    static void findAugment() {
        Arrays.fill(distArr, INF64);
        Arrays.fill(predArr, -1);
        Arrays.fill(peArr, -1);
        Arrays.fill(inQueueFlag, 0);
        distArr[src] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(src);
        inQueueFlag[src] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueueFlag[u] = 0;
            for (int eIdx : adj[u]) {
                if (residual(eIdx) == 0) continue;
                Edge e = edgesList.get(eIdx);
                int y = e.y;
                if (distArr[y] > distArr[u] + e.cost) {
                    distArr[y] = distArr[u] + e.cost;
                    predArr[y] = u;
                    peArr[y] = eIdx;
                    if (inQueueFlag[y] == 0) {
                        inQueueFlag[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = tgt;
        while (cur != src) {
            int eIdx = peArr[cur];
            edgesList.get(eIdx).flow++;
            edgesList.get(eIdx ^ 1).flow--;
            cur = predArr[cur];
        }
        totalCostAccum += distArr[tgt];
    }

    static void createEdge(int x, int y, int cap, int cst) {
        adj[x].add(edgesList.size());
        edgesList.add(new Edge(y, cap, 0, cst));
        adj[y].add(edgesList.size());
        edgesList.add(new Edge(x, 0, 0, -cst));
    }

    static void readData() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            createEdge(src, x, 1, 0);
        }
        int layers = 101;
        for (int i = 0; i < layers; i++) {
            createEdge(i * n, tgt, k, i * c);
        }
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            for (int t = 0; t < layers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    createEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < layers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    createEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < layers - 1; j++) {
                createEdge(i + j * n, i + j * n + n, k, 0);
            }
        }
        for (int i = 0; i < k; i++) {
            findAugment();
        }
        System.out.println(totalCostAccum);
        sc.close();
    }

    public static void main(String[] args) {
        readData();
        // No extra processing
    }
}
